<script lang="ts">
import { defineComponent, nextTick } from 'vue';
import { clearBookSources, getBook, mergeBookSources, type Book } from '../../api/books';
import type { AltSource, Chapter } from '../../api/models';
import { getChapterContent, getChapterImageUrl, getFontUrl, listFonts, switchBookSource, waitForCatalog, type ChapterContent, type Font } from '../../api/reader';
import { getChineseConversionCapability, type ChineseConversionCapability } from '../../api/system';
import AppButton from '../../ui/components/AppButton.vue';
import { convertReaderDisplay } from './chinese-conversion';
import { adjacentChapterIndex, clampProgress, normalizedScroll, resolveChapterIndex, scrollTopForProgress } from './reading-progress';
import { readerKeyboardAction } from './reader-keyboard';
import { isAtScrollBoundary, readerTapAction } from './reader-tap-navigation';
import { getProgressVersion, queueProgressWrite, setProgressVersion, waitForProgressWrites } from './progress-writer';
import { loadReaderPreferences, saveReaderPreferences, type ReaderPreferences } from './reader-preferences';
import ReaderBookmarksSheet from './ReaderBookmarksSheet.vue';
import ReaderControlIcon from './ReaderControlIcon.vue';
import ReaderSettingsSheet from './ReaderSettingsSheet.vue';
import ReaderSourceSheet from './ReaderSourceSheet.vue';
import ReaderTocSheet from './ReaderTocSheet.vue';
import { createReaderWakeLock } from './wake-lock';

export default defineComponent({
  name: 'ReaderView', components: { AppButton, ReaderBookmarksSheet, ReaderControlIcon, ReaderSettingsSheet, ReaderSourceSheet, ReaderTocSheet },
  data() { return { book: null as Book | null, chapters: [] as Chapter[], displayChapters: [] as Chapter[], content: null as ChapterContent | null, displayContent: null as ChapterContent | null, fonts: [] as Font[], fontsLoaded: false, fontsLoading: null as Promise<void> | null, conversionCapability: null as ChineseConversionCapability | null, currentIndex: 0, sourceId: '', sourceUrl: '', contentSourceUrl: '', loading: true, error: '', catalogFailed: false, catalogRetrying: false, progressError: '', conversionError: '', sourceError: '', sourceMessage: '', switching: false, chromeVisible: true, activeSheet: '' as ''|'toc'|'settings'|'bookmarks'|'sources', preferences: loadReaderPreferences(), lastPosition: 0, restoring: false, generation: 0, conversionGeneration: 0, wakeLockController: null as ReturnType<typeof createReaderWakeLock>|null, wakeLockWarning: '', progressTimer: undefined as ReturnType<typeof setTimeout>|undefined, persistence: Promise.resolve() as Promise<void>, suppressRouteLoad: false };  },
  computed: {
    bookId(): string { return String(this.$route.params.bookId || ''); },
    routeChapter(): number | undefined { const value=Number(this.$route.params.chapterIndex); return Number.isInteger(value)&&value>=0?value:undefined; },
    routePosition(): number | undefined { const value=Number(this.$route.query.position); return Number.isFinite(value)?clampProgress(value):undefined; },
    previousIndex(): number|null { return adjacentChapterIndex(this.chapters,this.currentIndex,-1); },
    nextIndex(): number|null { return adjacentChapterIndex(this.chapters,this.currentIndex,1); },
    currentTitle(): string { return this.displayContent?.title || this.displayChapters.find(chapter=>chapter.index===this.currentIndex)?.title || ''; },
    fontFamily(): string { return this.preferences.fontId==='system'?'var(--font-literary)':`reader-font-${this.preferences.fontId}, var(--font-literary)`; },
    readerStyle(): Record<string,string> { return { '--reader-bg':this.preferences.background,'--reader-text':this.preferences.textColor,'--reader-size':`${this.preferences.fontSize}px`,'--reader-line':String(this.preferences.lineHeight),'--reader-weight':String(this.preferences.fontWeight),'--reader-width':`${this.preferences.pageWidth}px`,'--reader-font':this.fontFamily }; },
    recoveryNeeded(): boolean { return Boolean(this.error); },
  },
  watch: {
    '$route.fullPath'() { if (this.suppressRouteLoad) { this.suppressRouteLoad=false; return; } void this.load(); },
    preferences: { deep:true, handler(value:ReaderPreferences) { saveReaderPreferences(value); } },
    'preferences.chineseConversion'() { void this.changeConversion(); },
    'preferences.keepScreenAwake'() { this.wakeLockWarning=''; void this.wakeLockController?.sync(); },
  },
  async mounted() { window.addEventListener('keydown', this.onKeydown); this.wakeLockController=createReaderWakeLock(()=>this.preferences.keepScreenAwake,()=>{this.wakeLockWarning=this.$t('reader.settings.wakeLockUnavailable')});await this.wakeLockController.sync();void this.loadConversionCapability();await this.load(); if(this.preferences.fontId!=='system')void this.loadFonts(); },
  beforeUnmount() { this.generation+=1; window.removeEventListener('keydown', this.onKeydown);void this.wakeLockController?.destroy();if(this.progressTimer)clearTimeout(this.progressTimer); void this.persistProgress(); },
  methods: {
    async load() {
      const request=++this.generation; this.loading=true; this.error=''; this.catalogFailed=false;
      try { await waitForProgressWrites(this.bookId); const bookRequest=getBook(this.bookId).then(value=>({value,error:null as unknown}),error=>({value:null,error})); const chaptersRequest=waitForCatalog(this.bookId,{isCurrent:()=>request===this.generation}).then(value=>({value,error:null as unknown,catalogError:false}),error=>({value:null,error,catalogError:true})); const bookResult=await bookRequest; if(request!==this.generation)return; if(bookResult.error)throw bookResult.error; const book=bookResult.value; if(!book)throw new Error(this.$t('reader.errors.load')); this.book=book;this.sourceId=book.sourceId;this.sourceUrl=book.sourceUrl;setProgressVersion(this.bookId,book.stateVersion); const chaptersResult=await chaptersRequest; if(request!==this.generation)return; if(chaptersResult.error){const error=chaptersResult.error;this.catalogFailed=chaptersResult.catalogError;throw error} const chapters=chaptersResult.value||[]; this.chapters=chapters; const index=resolveChapterIndex(chapters,this.routeChapter,book.durChapterIndex); if(index===null)throw new Error(this.$t('reader.errors.noReadable')); const position=this.routePosition ?? (index===book.durChapterIndex?book.durChapterPos:0); await this.loadContent(index,position,request); }
      catch(cause){if(request!==this.generation)return;this.error=cause instanceof Error?cause.message:this.$t('reader.errors.load');this.loading=false;this.chromeVisible=true;this.activeSheet='sources'}
    },
    async retryCatalog(){if(this.catalogRetrying)return;this.catalogRetrying=true;const request=++this.generation;this.loading=true;this.error='';this.catalogFailed=false;try{const chapters=await waitForCatalog(this.bookId,{retry:true,isCurrent:()=>request===this.generation});if(request!==this.generation)return;this.chapters=chapters;const index=resolveChapterIndex(chapters,this.routeChapter,this.book?.durChapterIndex??0);if(index===null)throw new Error(this.$t('reader.errors.noReadable'));const position=this.routePosition??(index===this.book?.durChapterIndex?this.book.durChapterPos:0);await this.loadContent(index,position,request)}catch(cause){if(request!==this.generation)return;this.catalogFailed=true;this.error=cause instanceof Error?cause.message:this.$t('reader.errors.load');this.loading=false;this.chromeVisible=true}finally{if(request===this.generation)this.catalogRetrying=false}},
    async loadContent(index:number,position:number,request?:number) { request ??= this.generation; const content=await getChapterContent(this.bookId,index);if(request!==this.generation)return;this.currentIndex=index;this.content=content;this.contentSourceUrl=this.sourceId;this.lastPosition=position;await this.refreshDisplay();if(request!==this.generation)return;this.loading=false;this.error='';await this.restore(position,request);if(this.book&&index!==this.book.durChapterIndex)await this.queueProgress(index,position);document.title=`${this.displayContent?.title || content.title} · ${this.book?.name || 'NovelReader'}`; },
    async changeConversion(){const host=this.$refs.scrollHost as HTMLElement|undefined;const position=host?normalizedScroll(host.scrollTop,host.scrollHeight,host.clientHeight):this.lastPosition;await this.refreshDisplay();await nextTick();if(!host)return;this.restoring=true;host.scrollTop=scrollTopForProgress(position,host.scrollHeight,host.clientHeight);this.lastPosition=position;requestAnimationFrame(()=>{this.restoring=false});},
    async refreshDisplay(){const request=++this.conversionGeneration;try{const display=await convertReaderDisplay(this.chapters,this.content,this.preferences.chineseConversion);if(request!==this.conversionGeneration)return;this.displayChapters=display.chapters;this.displayContent=display.content;this.conversionError='';if(display.content)document.title=`${display.content.title} · ${this.book?.name || 'NovelReader'}`;}catch{if(request!==this.conversionGeneration)return;this.displayChapters=this.chapters;this.displayContent=this.content;this.conversionError=this.$t('reader.settings.conversionFailed');}},
    async restore(position:number,request:number){await nextTick();requestAnimationFrame(()=>{if(request!==this.generation)return;const host=this.$refs.scrollHost as HTMLElement|undefined;if(!host)return;this.restoring=true;host.scrollTop=scrollTopForProgress(position,host.scrollHeight,host.clientHeight);requestAnimationFrame(()=>{this.restoring=false})})},
    onScroll(){if(this.loading||this.restoring||!this.content)return;const host=this.$refs.scrollHost as HTMLElement;this.lastPosition=normalizedScroll(host.scrollTop,host.scrollHeight,host.clientHeight);if(this.progressTimer)clearTimeout(this.progressTimer);this.progressTimer=setTimeout(()=>void this.persistProgress(),600)},
    onKeydown(event:KeyboardEvent){const action=readerKeyboardAction(event,Boolean(this.activeSheet),window.getSelection()?.toString()||'');if(action==='none')return;event.preventDefault();if(action==='escape'){if(this.activeSheet){this.activeSheet='';return}void this.$router.push(`/books/${encodeURIComponent(this.bookId)}`);return}if(action==='previous'){void this.navigate(this.previousIndex);return}if(action==='next'){void this.navigate(this.nextIndex);return}const host=this.$refs.scrollHost as HTMLElement|undefined;if(!host)return;if(action==='top'){host.scrollTo({top:0,behavior:'smooth'});return}if(action==='bottom'){host.scrollTo({top:host.scrollHeight,behavior:'smooth'});return}host.scrollBy({top:(action==='page-up'?-1:1)*host.clientHeight*.82,behavior:'smooth'});},
    onReaderTap(event:MouseEvent){
      if(this.loading||!this.content||this.activeSheet)return;
      const host=this.$refs.scrollHost as HTMLElement|undefined;if(!host)return;
      const target=event.target as HTMLElement;if(target.closest('a,button,input,select,textarea,[role="button"]'))return;
      const sideNavigation=!window.matchMedia('(pointer: coarse)').matches;
      const action=readerTapAction(event.clientX,event.clientY,host.getBoundingClientRect(),sideNavigation);
      if(action==='none')return;
      if(action==='toggle-controls'){this.chromeVisible=!this.chromeVisible;return}
      if(action==='show-controls'){this.chromeVisible=true;return}
      if(action==='previous'){void this.navigate(this.previousIndex);return}
      if(action==='next'){void this.navigate(this.nextIndex);return}
      const direction=action==='scroll-up'?-1:1;
      if(isAtScrollBoundary(direction,host.scrollTop,host.scrollHeight,host.clientHeight)){void this.navigate(direction<0?this.previousIndex:this.nextIndex,direction<0?1:0);return}
      host.scrollBy({top:direction*host.clientHeight*.82,behavior:'smooth'});
    },
    persistProgress(){if(!this.content||!this.book||this.contentSourceUrl!==this.sourceId)return Promise.resolve();return this.queueProgress(this.currentIndex,this.lastPosition)},
    async queueProgress(index:number,position:number){try{await queueProgressWrite(this.bookId,{sourceId:this.sourceId,chapterIndex:index,position});this.progressError=''}catch{this.progressError=this.$t('reader.errors.progress')}},
    async navigate(index:number|null,position=0){if(index===null)return;if(this.progressTimer)clearTimeout(this.progressTimer);await this.persistProgress();this.activeSheet='';const request=++this.generation;this.error='';try{await this.loadContent(index,position,request);this.suppressRouteLoad=true;await this.$router.push({name:'reader',params:{bookId:this.bookId,chapterIndex:index},query:position?{position:String(position)}:{}})}catch(cause){if(request!==this.generation)return;this.loading=false;this.error=cause instanceof Error?cause.message:this.$t('reader.errors.load');this.chromeVisible=true;this.activeSheet='sources'}},
    async captureBookmark(){const host=this.$refs.scrollHost as HTMLElement;if(!this.content||!host||this.contentSourceUrl!==this.sourceId)throw new Error(this.$t('reader.errors.position'));this.lastPosition=normalizedScroll(host.scrollTop,host.scrollHeight,host.clientHeight);if(this.progressTimer)clearTimeout(this.progressTimer);await this.persistProgress();const stateVersion=getProgressVersion(this.bookId);if(stateVersion===undefined)throw new Error(this.$t('reader.errors.position'));return{position:this.lastPosition,stateVersion}},
    imageUrl(index:number){return getChapterImageUrl(this.bookId,this.currentIndex,index)},
    async openSettings(){this.activeSheet='settings';await Promise.all([this.loadFonts(),this.loadConversionCapability()])},
    async loadConversionCapability(){try{this.conversionCapability=await getChineseConversionCapability();if(!this.conversionCapability.available&&this.preferences.chineseConversion!=='original')this.preferences={...this.preferences,chineseConversion:'original'}}catch{/* retry when Typography opens */}},
    loadFonts(){if(this.fontsLoaded)return Promise.resolve();if(this.fontsLoading)return this.fontsLoading;this.fontsLoading=(async()=>{try{this.fonts=await listFonts();this.fontsLoaded=true;for(const font of this.fonts){const family=`reader-font-${font.id}`;const face=new FontFace(family,`url(${getFontUrl(font.id)})`);void face.load().then(loaded=>document.fonts.add(loaded)).catch(()=>undefined)}}catch{/* optional */}finally{this.fontsLoading=null}})();return this.fontsLoading},
    persistMatches(sources:AltSource[]){if(!this.book||!sources.length)return;this.persistence=this.persistence.then(async()=>{if(this.book)this.book=await mergeBookSources(this.book.id,sources)}).catch(cause=>{this.sourceError=cause instanceof Error?cause.message:this.$t('sourceRecovery.persistFailed')})},
    async clearAndRescan(){try{await this.persistence;if(!this.book)throw new Error(this.$t('reader.errors.load'));this.book=await clearBookSources(this.book.id);this.sourceMessage=this.$t('sourceRecovery.cleared');this.sourceError=''}catch(cause){this.sourceError=cause instanceof Error?cause.message:this.$t('sourceRecovery.clearFailed');throw cause}},
    async selectSource(source:AltSource){if(!this.book||this.switching)return;this.switching=true;this.sourceError='';this.sourceMessage='';if(this.progressTimer)clearTimeout(this.progressTimer);let switched=false;try{await this.persistProgress();await waitForProgressWrites(this.bookId);this.book=await mergeBookSources(this.book.id,[source]);const result=await switchBookSource(this.book.id,source.sourceId,source.sourceUrl,source.bookUrl);switched=true;this.book=result.book;this.sourceId=result.book.sourceId;this.sourceUrl=result.book.sourceUrl;setProgressVersion(this.bookId,result.book.stateVersion);const request=this.generation;const chapters=await waitForCatalog(this.bookId,{isCurrent:()=>request===this.generation});this.chapters=chapters;await this.refreshDisplay();const mapped=resolveChapterIndex(chapters,result.book.durChapterIndex,result.book.durChapterIndex);if(mapped===null)throw new Error(this.$t('reader.errors.noReadable'));this.sourceMessage=result.mapping==='title'?this.$t('sourceRecovery.switchedTitle'):this.$t('sourceRecovery.switchedIndex');this.error='';this.content=null;this.currentIndex=mapped;this.lastPosition=result.book.durChapterPos||0;if(mapped!==this.routeChapter){await this.loadContent(mapped,this.lastPosition);this.suppressRouteLoad=true;await this.$router.replace({name:'reader',params:{bookId:this.bookId,chapterIndex:mapped}})}else await this.loadContent(mapped,this.lastPosition)}catch(cause){const message=cause instanceof Error?cause.message:this.$t('sourceRecovery.switchFailed');this.sourceError=switched?this.$t('reader.errors.switchedReload',{message}):message;if(!this.content)this.error=this.sourceError}finally{this.switching=false}},
  },
});
</script>

<template><section class="reader" :style="readerStyle"><header v-show="chromeVisible" class="reader-header"><RouterLink :to="`/books/${encodeURIComponent(bookId)}`" class="back">{{ $t('reader.back') }}</RouterLink><div><strong>{{ book?.name || $t('reader.title') }}</strong><span>{{ currentTitle }}</span></div><div class="reader-header-actions"><span class="chapter-position">{{ currentIndex + 1 }} / {{ chapters.length }}</span><button type="button" :aria-label="$t('reader.bookmarks.title')" @click="activeSheet='bookmarks'"><ReaderControlIcon name="bookmark" /></button></div></header><main ref="scrollHost" class="reader-scroll" tabindex="0" :aria-label="$t('reader.readingArea')" @scroll.passive="onScroll" @click="onReaderTap"><article class="prose"><p v-if="loading && !content" class="state">{{ $t('reader.loading') }}</p><section v-else-if="error && !content" class="failure"><h1>{{ currentTitle || book?.name || $t('reader.errors.chapter') }}</h1><p role="alert">{{ error }}</p><div class="failure-actions"><AppButton v-if="catalogFailed" :busy="catalogRetrying" @click="retryCatalog">{{ $t('reader.retryCatalog') }}</AppButton><AppButton variant="secondary" @click="activeSheet='sources'">{{ $t('reader.recover') }}</AppButton></div></section><template v-else-if="displayContent"><h1>{{ displayContent.title }}</h1><aside v-if="error" class="content-failure" role="alert"><span>{{ error }}</span><AppButton variant="secondary" @click="activeSheet='sources'">{{ $t('reader.recover') }}</AppButton></aside><p v-if="conversionError" class="conversion-warning" role="status">{{ conversionError }}</p><p v-if="wakeLockWarning" class="conversion-warning" role="status">{{ wakeLockWarning }}</p><p v-if="displayContent.offlineCopy" class="offline" role="status">{{ $t('reader.offline') }}</p><template v-if="displayContent.blocks.length"><template v-for="(block,index) in displayContent.blocks" :key="index"><p v-if="block.type==='text'">{{ block.text }}</p><figure v-else><img :src="imageUrl(block.index)" :alt="$t('reader.imageAlt',{title:displayContent.title})" loading="lazy" decoding="async"></figure></template></template><p v-for="(paragraph,index) in displayContent.blocks.length?[]:displayContent.paragraphs" :key="index">{{ paragraph }}</p><p class="chapter-end">{{ $t('reader.chapterEnd') }}</p></template></article></main><p v-if="progressError" class="progress-error" role="status">{{ progressError }}</p><footer v-show="chromeVisible" class="reader-controls"><div class="reader-controls-inner"><button :disabled="previousIndex===null" @click="navigate(previousIndex)"><ReaderControlIcon name="previous" /><span>{{ $t('reader.previous') }}</span></button><button @click="activeSheet='toc'"><ReaderControlIcon name="toc" /><span>{{ $t('reader.toc.title') }}</span></button><button :class="{attention:recoveryNeeded}" @click="activeSheet='sources'"><ReaderControlIcon name="source" /><span>{{ $t('reader.sources.short') }}</span></button><button @click="openSettings"><span class="reader-aa" aria-hidden="true">Aa</span><span>{{ $t('reader.settings.title') }}</span></button><button :disabled="nextIndex===null" @click="navigate(nextIndex)"><ReaderControlIcon name="next" /><span>{{ $t('reader.next') }}</span></button></div></footer><ReaderSettingsSheet v-if="activeSheet==='settings'" v-model="preferences" :fonts="fonts" :conversion-capability="conversionCapability" @close="activeSheet=''" /><ReaderTocSheet v-if="activeSheet==='toc'" :chapters="displayChapters" :current-index="currentIndex" @open="navigate" @close="activeSheet=''" /><ReaderBookmarksSheet v-if="activeSheet==='bookmarks'&&book" :book-id="book.id" :source-id="sourceId" :chapter-index="currentIndex" :capture="captureBookmark" @open="navigate" @close="activeSheet=''" /><ReaderSourceSheet v-if="activeSheet==='sources'&&book" :book="book" :current-source="book.origin||book.sourceUrl" :switching="switching" :action-error="sourceError||error" :action-message="sourceMessage" :on-clear-and-rescan="clearAndRescan" @matches="persistMatches" @select="selectSource" @close="activeSheet=''" /></section></template>

